def show(label, f):
    try:
        print(label, repr(f()))
    except Exception as e:
        print(label, 'EXC', type(e).__name__, str(e) if not str(e).startswith(('dumps()', "'")) else '')

shared = [1]
nested = marshal.loads(marshal.dumps([shared, shared, {'k': shared}, {1, 2}]))
print(nested[0] is nested[1], nested[2]['k'] is nested[0], nested)
for c in CASES:
    show(c.hex(), lambda: marshal.loads(c))
    show(c.hex() + ' file', lambda: marshal.load(io.BytesIO(c + b'tail')))
    show(c.hex() + ' nocode', lambda: marshal.loads(c, allow_code=False))

def lab(s):
    return type(s).__name__ if isinstance(s, memoryview) else repr(s)

SAMPLES = [
    None, True, False, Ellipsis, StopIteration, 0, 1, -1, 2**31, -2**31 - 1, 2**64 + 5, -(2**100), 10**50,
    1.5, -0.0, float('inf'), 1 + 2j, b'', b'abc' * 100, '', 'caf\u00e9', 'x' * 300, '\ud800', '\U0001f600',
    (), (1,), tuple(range(300)), [1, [2, [3]]], {1: 2, 'a': (3, 4)}, set(), {1, 2, 3},
    frozenset(), frozenset({1, 2}), frozenset({(1, 2), (3, 4)}),
    slice(None), slice(1, 2, 3), slice('a', [1], {2: 3}), bytearray(b'abc'), memoryview(b'abc'),
]
for s in SAMPLES:
    for v in range(7):
        def rt():
            r = marshal.loads(marshal.dumps(s, v))
            return (type(r).__name__, r)
        show('rt %s v%d' % (lab(s), v), rt)
        def rtf():
            f = io.BytesIO()
            marshal.dump(s, f, v)
            f.seek(0)
            r = marshal.load(f)
            return (type(r).__name__, r, f.tell() == len(f.getvalue()))
        show('rtf %s v%d' % (lab(s), v), rtf)

print(marshal.version)
print(marshal.loads(marshal.dumps(1.5, 1)), marshal.loads(marshal.dumps((1, 2), 3)))
for kw in ({}, {'allow_code': False}, {'allow_code': True}):
    show('dumps kw %r' % (kw,), lambda: marshal.loads(marshal.dumps((1, 'a', [2]), **kw), **kw))
show('dumps version kw', lambda: type(marshal.dumps(1, version=2)))
show('dumps bad kw', lambda: type(marshal.dumps(1, foo=1)))
show('dumps allow_code positional', lambda: marshal.dumps(1, 5, False))
show('loads allow_code positional', lambda: marshal.loads(b'N', False))
show('loads str', lambda: marshal.loads('T'))
show('loads none', lambda: marshal.loads(None))

class I(int): pass
class S(set): pass
for obj in (I(), S(), type('T', (tuple,), {})(), type('L', (list,), {})(), type('D', (dict,), {})(), type('F', (float,), {})(), type('C', (complex,), {})(), object(), len, lambda: 1, NotImplemented, int):
    show('unmarshallable ' + type(obj).__name__, lambda: marshal.dumps(obj))
fs = frozenset([int])
for name, arg in (('tuple', (fs,)), ('list', [fs]), ('set', fs), ('dict key', {fs: 'x'}), ('dict value', {'x': fs}),
                  ('slice', slice(fs, fs))):
    show(name, lambda: marshal.dumps((arg, memoryview(b''))))

l = []
l.append(l)
show('recursive list', lambda: marshal.loads(marshal.dumps(l))[0] is not None)
show('recursive list identity', lambda: (lambda r: r[0] is r)(marshal.loads(marshal.dumps(l))))
d = {}
d[1] = d
show('recursive dict identity', lambda: (lambda r: r[1] is r)(marshal.loads(marshal.dumps(d))))
deep = None
for _ in range(3000):
    deep = [deep]
show('deep', lambda: marshal.dumps(deep))

a = {3, 1, 2, 'x', 'y', (1, 2), b'z', 4.5, frozenset({7})}
b = set()
for x in sorted(a, key=repr, reverse=True):
    b.add(x)
print(marshal.dumps(a) == marshal.dumps(b), marshal.dumps(frozenset(a)) == marshal.dumps(frozenset(b)))
print(bytes(x & 0x7f for x in marshal.dumps(a, 5)[:5]), marshal.dumps(frozenset({'b', 'a'}), 5)[:5])

for s in (slice(1, 2, 3), slice(None)):
    for v in range(6):
        show('slice v%d' % v, lambda: marshal.loads(marshal.dumps(s, v)))

def trunc():
    data = marshal.dumps(('hello', 'dolly', None, 2**70, 1.5, [1, 2], {'a': b'b'}, slice(1, 2)))
    for i in range(len(data)):
        try:
            marshal.loads(data[:i])
        except EOFError:
            pass
        else:
            return 'no EOF at %d' % i
    return 'ok'
show('truncated', trunc)

f = io.BytesIO()
for d in (1, 'abc', b'def', 1.0, (2, 'a', ['b', b'c'])):
    marshal.dump(d, f)
    f.write(b'0123')
f.seek(0)
for d in (1, 'abc', b'def', 1.0, (2, 'a', ['b', b'c'])):
    print(marshal.load(f) == d, f.read(4))
show('load eof', lambda: marshal.load(f))
for n, fn in (('dumps', marshal.dumps), ('dump', marshal.dump), ('loads', marshal.loads), ('load', marshal.load)):
    print(n, fn.__text_signature__)
